def decide(recipient_reputation, round_num, my_history):
    # Base threshold from original
    base_threshold = 0.5
    # Adjust threshold based on agent's own recent donation history (last 5 rounds)
    if len(my_history) >= 5:
        recent_rate = sum(my_history[-5:]) / 5.0
    else:
        recent_rate = sum(my_history) / max(len(my_history), 1)
    # If agent has been donating less recently, lower threshold (more generous)
    # If donating a lot, raise threshold (more selective)
    threshold_shift = 0.2 * (1.0 - recent_rate) - 0.1 * (round_num / 100.0)
    threshold = base_threshold + threshold_shift
    # Keep threshold within [0,1]
    threshold = max(0.0, min(1.0, threshold))
    return recipient_reputation > threshold
